targets.rawSql:
SELECT product_id, slug, entitlement_key, active, price_raw / 1e9 AS price, coin_symbol,
       duration_ms / 86400000.0 AS duration_days, updated_at AS chain_sampled_at, error
FROM frontier_commerce.product_status ORDER BY product_id;

SELECT last_success_at, last_poll_at, consecutive_errors, last_fetched, last_inserted,
       total_events, last_error_at, last_error
FROM frontier_commerce.poller_status WHERE id = 1;
